def count_multiples(s, l, r):
    """Count how many numbers in [l, r] are divisible by s"""
    return r // s - (l - 1) // s

n = int(input())
s = list(map(int, input().split()))
t = int(input())

for _ in range(t):
    l, r = map(int, input().split())

    # Convert to 0-indexed
    l -= 1
    r -= 1

    # Count how many ants are eaten
    eaten = 0

    # For each ant i in [l, r]
    for i in range(l, r + 1):
        # Count how many j > i where s_i divides s_j
        count = 0
        for j in range(i + 1, r + 1):
            if s[j] % s[i] == 0:
                count += 1

        # Count how many j < i where s_j divides s_i
        for j in range(l, i):
            if s[i] % s[j] == 0:
                count += 1

        # Check if this ant is freed
        if count == r - l:
            # This ant is freed, not eaten
            pass
        else:
            eaten += 1

    print(eaten)
