def longest_chain(n, strings):
    # Build graph
    graph = [[] for _ in range(101)]  # Numbers go up to 100
    for a, b in strings:
        graph[a].append(b)
        graph[b].append(a)

    # Use DFS with memoization to find longest path
    max_length = 0

    def dfs(node, visited):
        nonlocal max_length

        # Try all neighbors
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                dfs(neighbor, visited)
                visited.remove(neighbor)

                # Update max length
                if len(visited) > max_length:
                    max_length = len(visited)

        # Also consider the path ending at this node
        if len(visited) > max_length:
            max_length = len(visited)

    # Try all starting nodes
    for i in range(1, 101):
        if graph[i]:
            visited = set([i])
            dfs(i, visited)

    return max_length

# Read input
import sys

for line in sys.stdin:
    n = int(line.strip())
    if n == 0:
        break

    strings = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().strip().split())
        strings.append((a, b))

    result = longest_chain(n, strings)
    print(result)
