import sys

def solve():
    t = int(sys.stdin.readline())

    for _ in range(t):
        # Place queen at (1, 1)
        print("1 1")
        sys.stdout.flush()

        queen_x, queen_y = 1, 1

        for move_num in range(130):
            # Get king's move
            direction = sys.stdin.readline().strip()

            if direction == "Done":
                break

            # Update queen's position based on king's move
            if direction == "Left":
                queen_y += 1
            elif direction == "Right":
                queen_y -= 1
            elif direction == "Up":
                queen_x += 1
            elif direction == "Down":
                queen_x -= 1
            elif direction == "Down-Left":
                queen_y += 1
                queen_x -= 1
            elif direction == "Down-Right":
                queen_y -= 1
                queen_x -= 1
            elif direction == "Up-Left":
                queen_y += 1
                queen_x += 1
            elif direction == "Up-Right":
                queen_y -= 1
                queen_x += 1

            # Print new queen position
            print(f"{queen_x} {queen_y}")
            sys.stdout.flush()

            # Check if we've won
            if direction == "Done":
                break

if __name__ == "__main__":
    solve()
