def update_distances(n, dist, a, b, c):
    """Update distances after adding a new road between a and b with length c"""
    # Check if the new road creates shorter paths
    for i in range(n):
        for j in range(n):
            # Check if path i -> a -> b -> j is shorter
            if dist[i][a] + c + dist[b][j] < dist[i][j]:
                dist[i][j] = dist[i][a] + c + dist[b][j]
            # Check if path i -> b -> a -> j is shorter
            if dist[i][b] + c + dist[a][j] < dist[i][j]:
                dist[i][j] = dist[i][b] + c + dist[a][j]

    return dist

def solve():
    n = int(input())
    dist = []
    for _ in range(n):
        row = list(map(int, input().split()))
        dist.append(row)

    k = int(input())
    results = []

    for _ in range(k):
        a, b, c = map(int, input().split())
        a -= 1  # Convert to 0-indexed
        b -= 1

        # Update distances
        dist = update_distances(n, dist, a, b, c)

        # Calculate sum of all pairs
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                total += dist[i][j]

        results.append(str(total))

    print(' '.join(results))

solve()
