def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Calculate GCD of all elements
    overall_gcd = a[0]
    for num in a[1:]:
        overall_gcd = gcd(overall_gcd, num)

    # Calculate LCM of all elements
    overall_lcm = a[0]
    for num in a[1:]:
        overall_lcm = (overall_lcm * num) // gcd(overall_lcm, num)

    # The GCD of all LCMs is the GCD of all elements
    print(overall_gcd)

