def next_greater_element(arr):
    n = len(arr)
    next_greater = [None] * n
    stack = []

    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] <= arr[i]:
            stack.pop()
        if stack:
            next_greater[i] = arr[stack[-1]]
        else:
            next_greater[i] = None
        stack.append(i)
    return next_greater

def next_smaller_element(arr):
    n = len(arr)
    next_smaller = [None] * n
    stack = []

    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if stack:
            next_smaller[i] = arr[stack[-1]]
        else:
            next_smaller[i] = None
        stack.append(i)
    return next_smaller

import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        arr = [int(next(it)) for _ in range(n)]

        next_greater = next_greater_element(arr)
        next_smaller = next_smaller_element(arr)

        max_product = 0

        for i in range(n):
            if next_greater[i] is not None:
                max_product = max(max_product, arr[i] * next_greater[i])
            if next_smaller[i] is not None:
                max_product = max(max_product, arr[i] * next_smaller[i])

        print(max_product)

if __name__ == "__main__":
    solve()
"}

