def can_form(s):
    """Check if string s can be formed by appending suffixes of length 2 or 3 with no consecutive duplicates"""
    n = len(s)

    # dp[i] = set of suffixes that can end at position i
    dp = [set() for _ in range(n + 1)]
    dp[0].add(None)  # empty string

    for i in range(n):
        for suffix in dp[i]:
            if suffix is None:
                # Start of string, can append any suffix
                if i + 2 <= n:
                    dp[i+2].add(s[i:i+2])
                if i + 3 <= n:
                    dp[i+3].add(s[i:i+3])
            else:
                # Cannot append the same suffix consecutively
                if i + 2 <= n and s[i:i+2] != suffix:
                    dp[i+2].add(s[i:i+2])
                if i + 3 <= n and s[i:i+3] != suffix:
                    dp[i+3].add(s[i:i+3])

    return dp[n]

s = input().strip()
n = len(s)

# Find all possible suffixes
possible_suffixes = set()

# Try all possible root lengths
for root_len in range(5, n):
    remaining = s[root_len:]
    if len(remaining) == 0:
        continue

    suffixes = can_form(remaining)
    if suffixes:
        possible_suffixes.update(suffixes)

# Sort lexicographically
sorted_suffixes = sorted(possible_suffixes)

print(len(sorted_suffixes))
