def is_composite(n):
    if n < 2:
        return True  # 1 is not prime
    if n == 2 or n == 3:
        return False  # primes
    if n % 2 == 0 or n % 3 == 0:
        return True  # divisible by 2 or 3
    i = 5
    while i * i <= n:
        if n % i == 0:
            return True
        i += 2
        if i * i <= n:
            if n % i == 0:
                return True
            i += 4
    return False


