import sys

def cross(o, a, b):
    """Cross product of vectors OA and OB"""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def dot(o, a, b):
    """Dot product of vectors OA and OB"""
    return (a[0] - o[0]) * (b[0] - o[0]) + (a[1] - o[1]) * (b[1] - o[1])

def dist_sq(a, b):
    """Squared distance between points a and b"""
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def is_point_on_segment(p, a, b):
    """Check if point p lies on segment ab"""
    # Check if p is collinear with a and b
    if abs(cross(a, b, p)) > 1e-8:
        return False

    # Check if p is between a and b
    return 0 <= dot(a, b, p) <= dist_sq(a, b)

def angle_condition(a, b, c):
    """Check if angle at point b between segments ba and bc is ≤ 90 degrees"""
    # Vectors ba and bc
    ba = (a[0] - b[0], a[1] - b[1])
    bc = (c[0] - b[0], c[1] - b[1])

    # Dot product of ba and bc
    dot_product = ba[0] * bc[0] + ba[1] * bc[1]

    # If dot product is negative, angle > 90 degrees
    return dot_product >= 0

def proportion_condition(seg, point):
    """Check if point divides segment in proportion ≥ 1/4"""
    a, b = seg
    pa = dist_sq(a, point)
    pb = dist_sq(b, point)

    # Find the shorter and longer parts
    if pa < pb:
        shorter = pa
        longer = pb
    else:
        shorter = pb
        longer = pa

    # Check proportion condition
    return shorter / longer >= 1/4

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        # Read three segments
        segments = []
        for _ in range(3):
            x1, y1, x2, y2 = map(int, data[idx:idx+4])
            segments.append(((x1, y1), (x2, y2)))
            idx += 4

        found = False

        # Try all permutations of which segment is first, second, third
        for first_idx in range(3):
            for second_idx in range(3):
                if first_idx == second_idx:
                    continue
                third_idx = 3 - first_idx - second_idx

                first = segments[first_idx]
                second = segments[second_idx]
                third = segments[third_idx]

                # Check if first and second share a common endpoint
                common = None
                for p in first:
                    if p in second:
                        common = p
                        break
                if common is None:
                    continue

                # Check if third connects two points on different segments
                p1 = None
                p2 = None
                for p in third:
                    if is_point_on_segment(p, first[0], first[1]):
                        p1 = p
                    elif is_point_on_segment(p, second[0], second[1]):
                        p2 = p

                if p1 is None or p2 is None:
                    continue

                # Check angle condition
                if not angle_condition(first[0], common, first[1]) and not angle_condition(first[1], common, first[0]):
                    continue

                # Check proportion conditions
                if proportion_condition(first, p1) and proportion_condition(second, p2):
                    found = True
                    break
            if found:
                break

        print("YES" if found else "NO")

if __name__ == "__main__":
    solve()
