def shortest_supersequence(strings):
    n = len(strings)

    # Precompute shortest common supersequence for all pairs
    scs = [[0] * n for _ in range(n)]

    # For each pair of strings, compute SCS length
    for i in range(n):
        for j in range(n):
            # Compute SCS length using DP
            m = len(strings[i])
            k = len(strings[j])

            # dp[i][j] = length of SCS of strings[i] and strings[j]
            dp = [[0] * (k + 1) for _ in range(m + 1)]

            for a in range(m + 1):
                for b in range(k + 1):
                    if a == 0:
                        dp[a][b] = b
                    elif b == 0:
                        dp[a][b] = a
                    elif strings[i][a-1] == strings[j][b-1]:
                        dp[a][b] = dp[a-1][b-1] + 1
                    else:
                        dp[a][b] = min(dp[a-1][b], dp[a][b-1]) + 1

            scs[i][j] = dp[m][k]

    # DP with bitmask
    # dp[mask] = (length of supersequence, supersequence string)
    dp = {}

    # Initialize with single strings
    for i in range(n):
        dp[1 << i] = (len(strings[i]), strings[i])

    # Try to build up from smaller masks
    for mask in range(1, 1 << n):
        if mask not in dp:
            continue

        length, superseq = dp[mask]

        # Try to add each string not in the mask
        for i in range(n):
            if not (mask & (1 << i)):
                # Compute SCS of superseq and strings[i]
                m = len(superseq)
                k = len(strings[i])

                # dp_scs[i][j] = length of SCS of superseq and strings[i]
                dp_scs = [[0] * (k + 1) for _ in range(m + 1)]

                for a in range(m + 1):
                    for b in range(k + 1):
                        if a == 0:
                            dp_scs[a][b] = b
                        elif b == 0:
                            dp_scs[a][b] = a
                        elif superseq[a-1] == strings[i][b-1]:
                            dp_scs[a][b] = dp_scs[a-1][b-1] + 1
                        else:
                            dp_scs[a][b] = min(dp_scs[a-1][b], dp_scs[a][b-1]) + 1

                new_length = dp_scs[m][k]
                new_mask = mask | (1 << i)

                if new_mask not in dp or new_length < dp[new_mask][0]:
                    dp[new_mask] = (new_length, superseq + strings[i])

    # Return the minimum length for all strings
    return dp[(1 << n) - 1][0]

