# Build adjacency list
adj = [[] for _ in range(n)]
for i in range(n):
    for j in range(i + 1, n):
        if (a[i] & a[j]) != 0:
            adj[i].append(j)
            adj[j].append(i)

# Check for triangles (cycles of length 3)
for i in range(n):
    for j in adj[i]:
        for k in adj[j]:
            if k != i and (a[k] & a[i]) != 0:
                print(3)
                exit()

# Check for quadrilaterals (cycles of length 4)
for i in range(n):
    for j in adj[i]:
        for k in adj[j]:
            if k != i:
                for l in adj[k]:
                    if l != i and (a[l] & a[i]) != 0:
                        print(4)
                        exit()

# If we get here, there are no cycles
print(-1)
