    # If f > n, it's impossible to give each friend at least 1 sweet
    if f > n:
        print(0)
        continue

    # Total ways to distribute n sweets to f friends with each getting at least 1
    total = comb(n - 1, f - 1, MOD, fact, inv_fact)

    # Find all divisors of n > 1
    divisors = []
    for d in range(2, int(math.isqrt(n)) + 1):
        if n % d == 0:
            divisors.append(d)
            if d != n // d:
                divisors.append(n // d)
    if n > 1:
        divisors.append(n)

    # Subtract the bad cases
    bad = 0
    for d in divisors:
        if d > 1:
            # Number of compositions of n/d into f parts
            bad = (bad + comb((n // d) - 1, f - 1, MOD, fact, inv_fact)) % MOD

    answer = (total - bad) % MOD
    print(answer)

